test.afterAll(async({},info:TestInfo)=>{const{stat}=require('node:fs/promises')as typeof import('node:fs/promises');for(const evidence of completed.values()){let missing=false;try{await stat(evidence.directory);}catch(reason){if((reason as NodeJS.ErrnoException).code==='ENOENT')missing=true;else throw reason;}expect(missing).toBe(true);await info.attach('SQLite字段重建最终目录清理',{body:JSON.stringify({...evidence,directoryRemoved:true,accepted:true,launches:2}),contentType:'application/json'});}});
